ADMIN_HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>VoiceRecap Admin</title>
<style>
:root{font-family:Inter,system-ui,sans-serif;color:#e8eef5;background:#0b1120}body{margin:0}header{padding:18px 24px;border-bottom:1px solid #22304a;display:flex;justify-content:space-between;align-items:center;background:#101a2d}h1{font-size:20px;margin:0}main{max-width:1400px;margin:auto;padding:24px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px}.card{background:#111c30;border:1px solid #243653;border-radius:14px;padding:16px;box-shadow:0 8px 30px #0003}.metric{font-size:30px;font-weight:700;margin-top:8px}.muted{color:#91a2bc}.tabs{display:flex;gap:8px;flex-wrap:wrap;margin:20px 0}.tabs button,.primary{background:#3568e8;color:white;border:0;border-radius:9px;padding:10px 14px;cursor:pointer}.tabs button.secondary{background:#1b2a45}.panel{display:none}.panel.active{display:block}.row{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:10px}input,select,textarea{background:#0b1425;color:#e8eef5;border:1px solid #304565;border-radius:8px;padding:10px;min-width:160px}table{border-collapse:collapse;width:100%;font-size:13px}th,td{border-bottom:1px solid #253653;padding:9px;text-align:left;vertical-align:top}th{color:#a9bcda}button.small{padding:6px 9px;font-size:12px;border:0;border-radius:6px;background:#294b86;color:white;cursor:pointer}.danger{background:#8e3142!important}.ok{color:#70e0a2}.warn{color:#ffd27a}.error{color:#ff8598}.toast{position:fixed;right:20px;bottom:20px;background:#1d2e4e;padding:12px 16px;border-radius:9px;display:none}.formgrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px}.formgrid label{display:flex;flex-direction:column;gap:5px;color:#9db0cd;font-size:12px}.wide{grid-column:1/-1}.badge{padding:3px 7px;border-radius:99px;background:#203b69}
</style></head><body>
<header><h1>VoiceRecap Control Center</h1><div class="row"><span id="who" class="muted">Signed out</span><button class="small" onclick="logout()">Logout</button></div></header>
<main>
<section id="login" class="card"><h2>Admin sign in</h2><p class="muted">Use the same VoiceRecap account marked as administrator.</p><div class="row"><input id="email" type="email" placeholder="admin email"><input id="password" type="password" placeholder="password"><button class="primary" onclick="login()">Sign in</button></div><div id="loginError" class="error"></div></section>
<section id="app" style="display:none">
<div class="grid" id="metrics"></div>
<div class="tabs"><button onclick="tab('users')">Users</button><button class="secondary" onclick="tab('plans')">Plans & pricing</button><button class="secondary" onclick="tab('payments')">Payments</button><button class="secondary" onclick="tab('slots')">Gemini accounts</button><button class="secondary" onclick="tab('jobs')">Jobs</button><button class="secondary" onclick="tab('audit')">Audit log</button></div>
<section id="users" class="panel active card"><h2>User management</h2><div class="row"><input id="userQuery" placeholder="Search email/name"><button class="primary" onclick="loadUsers()">Search</button></div><div id="usersTable"></div></section>
<section id="plans" class="panel card"><h2>Plan and credit pricing</h2><p class="muted">Create plans with credits, per-video credit cost, MMK price, and USDT price. Values are intentionally admin-controlled.</p><div class="formgrid"><label>Name<input id="pName" placeholder="Creator 100"></label><label>Description<input id="pDesc"></label><label>Included credits<input id="pCredits" type="number" min="0" value="100"></label><label>Credits per video<input id="pVideo" type="number" min="0" value="10"></label><label>Extra credits per minute<input id="pMinute" type="number" min="0" value="0"></label><label>TTS credits / 100 chars<input id="pTts" type="number" min="0" value="1"></label><label>Voice clone credits<input id="pClone" type="number" min="0" value="0"></label><label>Price MMK<input id="pMmk" type="number" min="0" value="0"></label><label>Price USDT<input id="pUsdt" value="0"></label><label>Validity days<input id="pDays" type="number" min="0" value="30"></label><label>Max video seconds<input id="pMax" type="number" min="1" value="1800"></label><label>Sort order<input id="pSort" type="number" value="10"></label></div><br><button class="primary" onclick="createPlan()">Create plan</button><div id="plansTable"></div></section>
<section id="payments" class="panel card"><h2>Payment review</h2><p class="muted">Approve only after checking the submitted MMK or USDT transaction externally. Approval grants the plan credits exactly once.</p><div id="paymentsTable"></div></section>
<section id="slots" class="panel card"><h2>Gemini account/project slots</h2><p class="muted">The secret value stays in Worker secrets. This panel stores only the secret binding name and non-secret quota metadata.</p><div class="formgrid"><label>Account label<input id="sAccount"></label><label>Project ID<input id="sProject"></label><label>Model<input id="sModel" value="gemini-2.5-flash-lite"></label><label>Priority (0 first)<input id="sPriority" type="number" value="0"></label><label>Secret binding name<input id="sSecret" value="GEMINI_KEY_1"></label><label>RPM limit<input id="sRpm" type="number" value="10"></label><label>Daily limit<input id="sDaily" type="number" value="100"></label><label>Concurrency<input id="sConc" type="number" value="1"></label></div><br><button class="primary" onclick="createSlot()">Add account slot</button><div id="slotsTable"></div></section>
<section id="jobs" class="panel card"><h2>Processing jobs</h2><div id="jobsTable"></div></section>
<section id="audit" class="panel card"><h2>Immutable audit trail</h2><div id="auditTable"></div></section>
</section></main><div id="toast" class="toast"></div>
<script>
const state={token:localStorage.getItem('vr_admin_access')};const $=id=>document.getElementById(id);function api(path,opt={}){opt.headers={...(opt.headers||{}),Authorization:`Bearer ${state.token}`,'Content-Type':'application/json'};return fetch(path,opt).then(async r=>{const b=await r.json().catch(()=>({}));if(!r.ok)throw new Error(b.detail||`HTTP ${r.status}`);return b})}function toast(x){$('toast').textContent=x;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',3500)}function esc(x){return String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function table(rows,cols,actions=''){if(!rows?.length)return '<p class="muted">No records.</p>';return `<table><thead><tr>${cols.map(c=>`<th>${esc(c[1])}</th>`).join('')}<th></th></tr></thead><tbody>${rows.map(r=>`<tr>${cols.map(c=>`<td>${esc(typeof c[0]==='function'?c[0](r):r[c[0]])}</td>`).join('')}<td>${actions?actions(r):''}</td></tr>`).join('')}</tbody></table>`}function tab(id){document.querySelectorAll('.panel').forEach(x=>x.classList.remove('active'));$(id).classList.add('active');({users:loadUsers,plans:loadPlans,payments:loadPayments,slots:loadSlots,jobs:loadJobs,audit:loadAudit}[id]||(()=>{}))()}async function login(){try{const b=await fetch('/api/v1/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:$('email').value,password:$('password').value})}).then(async r=>{const x=await r.json();if(!r.ok)throw Error(x.detail||'Sign in failed');return x});state.token=b.access_token;localStorage.setItem('vr_admin_access',state.token);await init()}catch(e){$('loginError').textContent=e.message}}function logout(){localStorage.removeItem('vr_admin_access');location.reload()}async function init(){try{const me=await api('/api/v1/auth/me');if(!me.is_admin)throw Error('This account is not an administrator');$('login').style.display='none';$('app').style.display='block';$('who').textContent=me.email;await Promise.all([loadSummary(),loadUsers(),loadPlans()])}catch(e){localStorage.removeItem('vr_admin_access');$('loginError').textContent=e.message}}async function loadSummary(){const x=await api('/api/v1/admin/summary');$('metrics').innerHTML=Object.entries(x).map(([k,v])=>`<div class="card"><div class="muted">${esc(k.replaceAll('_',' '))}</div><div class="metric">${esc(v)}</div></div>`).join('')}async function loadUsers(){const x=await api('/api/v1/admin/users?q='+encodeURIComponent($('userQuery').value));$('usersTable').innerHTML=table(x,[['email','Email'],['display_name','Name'],['credits','Credits'],['is_active','Active'],['is_banned','Banned'],['created_at','Created']],r=>`<button class="small" onclick="grant('${r.id}')">Grant</button> <button class="small danger" onclick="ban('${r.id}',${!r.is_banned})">${r.is_banned?'Unban':'Ban'}</button>`)}async function grant(id){const n=prompt('Credits to grant');if(!n)return;const description=prompt('Reason','Admin grant');if(!description)return;await api('/api/v1/admin/credits/grant',{method:'POST',body:JSON.stringify({user_id:id,credits:Number(n),description,idempotency_key:'admin-'+id+'-'+Date.now()})});toast('Credits granted');await loadUsers()}async function ban(id,b){await api('/api/v1/admin/users/'+id,{method:'PATCH',body:JSON.stringify({is_banned:b})});toast('User updated');await loadUsers()}async function loadPlans(){const x=await api('/api/v1/admin/plans');$('plansTable').innerHTML='<br>'+table(x,[['name','Name'],['included_credits','Credits'],['video_credit_cost','Video cost'],['price_mmk','MMK'],['price_usdt','USDT'],['active','Active'],['validity_days','Days']],r=>`<button class="small" onclick="togglePlan('${r.id}',${!r.active})">${r.active?'Disable':'Enable'}</button>`)}async function createPlan(){const b={name:$('pName').value,description:$('pDesc').value||null,included_credits:Number($('pCredits').value),video_credit_cost:Number($('pVideo').value),video_credit_cost_per_minute:Number($('pMinute').value),tts_credit_per_100_chars:Number($('pTts').value),voice_clone_credit_cost:Number($('pClone').value),price_mmk:Number($('pMmk').value),price_usdt:$('pUsdt').value,validity_days:Number($('pDays').value),max_video_duration_seconds:Number($('pMax').value),sort_order:Number($('pSort').value),active:true};await api('/api/v1/admin/plans',{method:'POST',body:JSON.stringify(b)});toast('Plan created');await loadPlans()}async function togglePlan(id,active){const x=await api('/api/v1/admin/plans');const p=x.find(a=>a.id===id);p.active=active;await api('/api/v1/admin/plans/'+id,{method:'PATCH',body:JSON.stringify(p)});await loadPlans()}async function loadPayments(){const x=await api('/api/v1/admin/payments');$('paymentsTable').innerHTML=table(x,[['email','User'],['plan_name','Plan'],['currency','Currency'],['amount','Amount'],['status','Status'],['transaction_reference','Reference'],['created_at','Created']],r=>r.status==='submitted'?`<button class="small" onclick="approve('${r.id}')">Approve</button>`:'')}async function approve(id){if(!confirm('Approve and grant credits?'))return;await api('/api/v1/admin/payments/'+id+'/approve',{method:'POST'});toast('Payment approved');await loadPayments();await loadSummary()}async function loadSlots(){const x=await api('/api/v1/admin/gemini-slots');$('slotsTable').innerHTML='<br>'+table(x,[['account_id','Account'],['project_id','Project'],['model','Model'],['priority','Priority'],['secret_name','Secret'],['active_jobs','Active'],['daily_used','Daily'],['cooldown_until','Cooldown']],r=>`<span class="badge">${r.enabled?'enabled':'disabled'}</span>`)}async function createSlot(){const b={account_id:$('sAccount').value,project_id:$('sProject').value,model:$('sModel').value,priority:Number($('sPriority').value),secret_name:$('sSecret').value,enabled:true,rpm_limit:Number($('sRpm').value),daily_limit:Number($('sDaily').value),concurrency_limit:Number($('sConc').value)};await api('/api/v1/admin/gemini-slots',{method:'POST',body:JSON.stringify(b)});toast('Slot added');await loadSlots()}async function loadJobs(){const x=await api('/api/v1/admin/jobs');$('jobsTable').innerHTML=table(x,[['email','User'],['status','Status'],['target_language','Language'],['credits_reserved','Reserved'],['provider_model','Model'],['error_message','Error'],['created_at','Created']])}async function loadAudit(){const x=await api('/api/v1/admin/audit');$('auditTable').innerHTML=table(x,[['created_at','Time'],['action','Action'],['actor_user_id','Actor'],['target_type','Target'],['target_id','Target ID'],['metadata_json','Metadata']])}if(state.token)init();
</script></body></html>'''
